    "cli",
    "project-management",
    "lookup",
    "kim"
  ],
  "author": "Kim",
  "license": "MIT",
  "dependencies": {
    "express": "^4.18.2",
    "chalk": "^4.1.2",
    "table": "^6.8.0"
  }
}

{
  "version": "1.0",
  "auto_sync": true,
  "sync_interval": 3600000,
  "categories": [
    "memory",
    "note",
    "insight",
    "bug",
    "todo"
