  "importance_levels": {
    "1": "low",
    "2": "minor",
    "3": "normal",
    "4": "high",
    "5": "critical"
  },
  "api": {
    "port": 40012,
    "host": "localhost",
    "enabled": true
  },
  "storage": {
    "base_dir": "memo",
    "index_file": "index.json",
    "per_project": "memory.json"
  },
  "export": {
    "format": "markdown",
    "include_timestamps": true,
    "include_tags": true
  }
}

