console.log('=== 🔴 근본 문제 분석 ===\n');

// 1. 문제 케이스
console.log('1️⃣ Status/Category 라벨로 인한 부당한 저평가:\n');

const problemCases = [
  'freelang-v6',
  'freelang-c-final',
  'mlir-cpp-learning',
  '1.1-minimal-rag'
];

problemCases.forEach(name => {
  const p = projects.find(x => x.name === name);
  if (!p) return;

  console.log(`${name}`);
  console.log(`  상태: ${p.status} | 카테고리: ${p.category}`);
  console.log(`  커밋: ${p.commit_count} | 90일: ${p.commit_count_90d}`);
  console.log(`  점수: ${p.health.score}/100`);
  console.log(`  - Activity: ${p.health.activityScore}/100 (Status="${p.status}"로 저평가)`);
  console.log(`  - Doc: ${p.health.docScore}/100 (Category="${p.category}"로 저평가)`);
  console.log('');
});

// 2. 재순위
console.log('\n2️⃣ 커밋 수로 재순위하면:\n');

const byCommits = projects
  .filter(p => p.commit_count)
  .sort((a,b) => b.commit_count - a.commit_count)
  .slice(0, 20);

byCommits.forEach((p, i) => {
  const newScore = Math.min(100, 30 + (p.commit_count || 0) * 2);
  console.log(`${(i+1).toString().padStart(2)}. ${p.name.padEnd(35)} | ${(p.commit_count || 0).toString().padStart(2)} commits | 현재: ${p.health.score.toString().padStart(2)}/100 | 제안: ${newScore.toString().padStart(2)}/100`);
});

// 3. 등급 재분포
console.log('\n\n3️⃣ 제안 알고리즘 (커밋 중심):\n');

console.log('새로운 공식:');
console.log('  Health = 30 + (commit_count × 1.5) + bonus');
console.log('  bonus:');
console.log('    - 90일 커밋 있음: +10');
console.log('    - 문서화 있음: +10');
console.log('    - v4/compiler/kernel: +10\n');

const newScores = projects.map(p => {
  let s = 30;
  if (p.commit_count) s += Math.min(50, (p.commit_count || 0) * 1.5);
  if (p.commit_count_90d) s += 10;
  if (p.description && p.description.length > 10) s += 10;
  if (/v4|compiler|kernel|runtime/.test(p.name)) s += 10;
  return Math.min(100, s);
});

const dist = {
  'A+ (90-100)': newScores.filter(s => s >= 90).length,
  'A (80-89)': newScores.filter(s => s >= 80 && s < 90).length,
  'B+ (70-79)': newScores.filter(s => s >= 70 && s < 80).length,
  'B (60-69)': newScores.filter(s => s >= 60 && s < 70).length,
  'C (50-59)': newScores.filter(s => s >= 50 && s < 60).length,
  'D (40-49)': newScores.filter(s => s >= 40 && s < 50).length,
  'F (0-39)': newScores.filter(s => s < 40).length,
};

console.log('예상 등급 분포:\n');
Object.entries(dist).forEach(([grade, count]) => {
  const pct = ((count / projects.length) * 100).toFixed(1);
  console.log(`  ${grade}: ${count.toString().padStart(3)} (${pct.padStart(5)}%)`);
});

const avg = newScores.reduce((a,b) => a+b, 0) / newScores.length;
console.log(`\n  평균: ${avg.toFixed(1)}/100`);

console.log('\n\n=== 결론 ===\n');
console.log('현재 (56/100):');
console.log('  ✅ B: 77개 (57.5%)');
console.log('  ✅ C: 32개 (23.9%)');
console.log('  ⚠️ D: 6개 (4.5%)');
console.log('  🔴 F: 19개 (14.2%) ← Status/Category 규제 때문!');

console.log('\n제안 (커밋 기반):\n');
console.log('  ✅ A/B: 대폭 증가');
console.log('  ✅ C: 안정');
console.log('  ⚠️ D: 감소');
console.log('  🔴 F: 1-2개만 (정말 버려진 것)');

console.log('\n✨ 핵심: \"라벨\"이 아니라 \"실제 활동\"으로 평가하자!');

