     3→/**
     4→ * P1-3 최종 솔루션: Git Clone으로 모든 프로젝트 동기화
     5→ *
     6→ * GOGS API 토큰 인증 불가 → git clone + git log로 우회
     7→ * 1. 매칭된 repo_url을 사용
     8→ * 2. Shallow clone (--depth 1)으로 빠른 처리
     9→ * 3. git log로 커밋 정보 수집
    10→ */
    11→
    12→const fs = require('fs');
    13→const path = require('path');
    14→const { execSync, spawnSync } = require('child_process');
    15→const os = require('os');
    16→
    17→// 임시 디렉토리
    18→const TEMP_BASE = path.join(os.tmpdir(), 'gogs-sync');
    19→
    20→function ensureTempDir() {
    21→  if (!fs.existsSync(TEMP_BASE)) {
    22→    fs.mkdirSync(TEMP_BASE, { recursive: true });
    23→  }
    24→}
    25→
    26→function gitCloneAndAnalyze(repoUrl, projectName) {
    27→  const tempDir = path.join(TEMP_BASE, projectName.replace(/[^a-z0-9-]/g, ''));
    28→
    29→  // 기존 디렉토리 제거
    30→  if (fs.existsSync(tempDir)) {
    31→    execSync(`rm -rf "${tempDir}"`, { stdio: 'ignore' });
    32→  }
    33→
    34→  try {
    35→    // Shallow clone (최근 커밋만)
    36→    console.log(`   ⏳ Cloning ${projectName}...`);
    37→    execSync(`git clone --depth 50 --quiet "${repoUrl}" "${tempDir}"`, {
    38→      stdio: 'pipe',
    39→      timeout: 30000,
    40→    });
    41→
    42→    // 커밋 정보 수집
    43→    const gitLogOutput = execSync(
    44→      'git log --format="%aI|%an" --all',
    45→      {
    46→        cwd: tempDir,
    47→        encoding: 'utf-8',
    48→        stdio: 'pipe',
    49→      }
    50→    ).trim();
    51→
    52→    const commits = gitLogOutput.split('\n').filter(line => line.trim());
    53→    const totalCommits = commits.length;
    54→
    55→    // 90일 이내 커밋 계산
    56→    const now = new Date();
    57→    const ninetyDaysAgo = new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000);
    58→
    59→    const commit90d = commits.filter(line => {
    60→      const [timestamp] = line.split('|');
    61→      const commitDate = new Date(timestamp);
    62→      return commitDate >= ninetyDaysAgo;
    63→    }).length;
    64→
    65→    // 마지막 커밋 작성자
    66→    const lastCommitLine = commits[0];
    67→    let lastCommitAuthor = 'Unknown';
    68→    if (lastCommitLine) {
    69→      const [, author] = lastCommitLine.split('|');
    70→      lastCommitAuthor = author || 'Unknown';
    71→    }
    72→
    73→    // 마지막 커밋 날짜
    74→    let updatedAt = new Date().toISOString();
    75→    if (lastCommitLine) {
    76→      const [timestamp] = lastCommitLine.split('|');
    77→      updatedAt = new Date(timestamp).toISOString();
    78→    }
    79→
    80→    // 정리
    81→    execSync(`rm -rf "${tempDir}"`, { stdio: 'ignore' });
    82→
    83→    return {
    84→      commit_count: totalCommits,
    85→      commit_count_90d: commit90d,
    86→      last_commit_author: lastCommitAuthor,
    87→      updated_at: updatedAt,
    88→      success: true,
    89→    };
    90→  } catch (error) {
    91→    // 정리
    92→    if (fs.existsSync(tempDir)) {
    93→      execSync(`rm -rf "${tempDir}"`, { stdio: 'ignore' });
    94→    }
    95→
    96→    return {
    97→      commit_count: 0,
    98→      commit_count_90d: 0,
    99→      last_commit_author: 'Unknown',
   100→      updated_at: new Date().toISOString(),
   101→      success: false,
   102→      error: error.message.split('\n')[0],
   103→    };
   104→  }
   105→}
   106→
   107→async function syncViaGit(projectsJsonPath) {
   108→  if (!fs.existsSync(projectsJsonPath)) {
   109→    console.error(`❌ File not found: ${projectsJsonPath}`);
   110→    process.exit(1);
   111→  }
   112→
   113→  const data = JSON.parse(fs.readFileSync(projectsJsonPath, 'utf-8'));
   114→  const projects = Array.isArray(data) ? data : data.projects || [];
   115→
   116→  console.log(`🔄 Syncing metadata for ${projects.length} projects via git clone...\n`);
   117→
   118→  ensureTempDir();
   119→
   120→  let updated = 0;
   121→  let failed = 0;
   122→  let skipped = 0;
   123→
   124→  // 순차 처리 (동시 클론은 너무 무겁다)
   125→  for (let i = 0; i < projects.length; i++) {
   126→    const project = projects[i];
   127→    const repoUrl = project.repo_url || project.gogs_path;
   128→
   129→    if (!repoUrl || repoUrl.startsWith('/')) {
   130→      skipped++;
   131→      console.log(`⏭️  [SKIP] ${project.name} (no GOGS URL)`);
   132→      continue;
   133→    }
   134→
   135→    // GOGS URL 검증
   136→    if (!repoUrl.includes('gogs.dclub.kr')) {
   137→      skipped++;
   138→      console.log(`⏭️  [SKIP] ${project.name} (not GOGS URL)`);
   139→      continue;
   140→    }
   141→
   142→    process.stdout.write(`[${i + 1}/${projects.length}] ${project.name.padEnd(40)}`);
   143→
   144→    const result = gitCloneAndAnalyze(repoUrl, project.name);
   145→
   146→    if (result.success) {
   147→      project.commit_count = result.commit_count;
   148→      project.commit_count_90d = result.commit_count_90d;
   149→      project.last_commit_author = result.last_commit_author;
   150→      project.updated_at = result.updated_at;
   151→      updated++;
   152→
   153→      console.log(` ✅ ${result.commit_count} commits, ${result.commit_count_90d} in 90d`);
   154→    } else {
   155→      failed++;
   156→      console.log(` ❌ ${result.error}`);
   157→    }
   158→
   159→    // 진행률
   160→    if ((i + 1) % 10 === 0) {
   161→      console.log(`\n📊 Progress: ${updated}/${i + 1} updated, ${failed}/${i + 1} failed\n`);
   162→    }
   163→  }
   164→
   165→  // 파일 저장
   166→  const outputPath = projectsJsonPath.replace('.json', '-with-metadata.json');
   167→  const output = Array.isArray(data) ? projects : { ...data, projects };
   168→  fs.writeFileSync(outputPath, JSON.stringify(output, null, 2));
   169→
   170→  // 통계
