   176→  console.log(`   📁 Output: ${outputPath}`);
   177→  console.log('='.repeat(60) + '\n');
   178→
   179→  // 정리
   180→  try {
   181→    execSync(`rm -rf "${TEMP_BASE}"`, { stdio: 'ignore' });
   182→  } catch (e) {
