#include <stdlib.h>
#include <string.h>
#include <stdint.h>

/* Forward declarations */
long factorial(long n);
int main(void);

long factorial(long n) {
    if ((n <= 1)) {
        return 1;
    }
    return (n * factorial((n - 1)));
}

int main(void) {
    return factorial(5);
}

